FOR UPDATE

SELECT

FROM inventory
WHERE location_id = #{locationId}
  AND sku_id = #{skuId}
  AND batch_no = #{batchNo}
  AND deleted = 0

SELECT i.id, i.warehouse_id, w.name AS warehouse_name, i.location_id, l.code AS location_code, i.sku_id, p.sku_code, p.name AS sku_name, i.batch_no, i.qty, i.locked_qty, i.frozen_qty, i.available_qty, i.inbound_time FROM inventory i LEFT JOIN warehouse w ON w.id = i.warehouse_id AND w.deleted = 0 LEFT JOIN location l ON l.id = i.location_id AND l.deleted = 0 LEFT JOIN product p ON p.id = i.sku_id WHERE i.deleted = 0
AND (p.sku_code LIKE CONCAT('%', #{query.keyword}, '%') OR p.name LIKE CONCAT('%', #{query.keyword}, '%') OR l.code LIKE CONCAT('%', #{query.keyword}, '%'))
AND i.warehouse_id = #{query.warehouseId}
AND i.sku_id = #{query.skuId}
AND i.location_id = #{query.locationId}
AND i.batch_no = #{query.batchNo}
ORDER BY i.id DESC
